Issue title: [IndVarSimplify] samesign flag should be dropped after narrowing
Detailed information:
BUG TYPE:
    miscompilation

VERIFICATION RESULT:
    Invalid refinement in @test_drop_icmp_samesign -- Source is more defined than target

VIOLATED PROPERTY:
    UB refinement

SOURCE (pre-transformation IR):
target datalayout = "e-p:64:64:64-i1:8:8-i8:8:8-i16:16:16-i32:32:32-i64:64:64-f32:32:32-f64:64:64-v64:64:64-v128:128:128-a0:0:64-s0:64:64-f80:128:128-n8:16:32:64"

define i8 @test_drop_icmp_samesign(i1 %cond, i32 range(i32 0, 32) %x) {
entry:
  br i1 %cond, label %for.body, label %else

else:                                             ; preds = %entry
  %call1 = call i8 @callee()
  br label %exit

for.body:                                         ; preds = %for.body, %entry
  %call2 = call i8 @callee()
  %ext = zext i8 %call2 to i32
  %cond2 = icmp samesign ugt i32 %x, %ext
  br i1 %cond2, label %for.body, label %exit

exit:                                             ; preds = %for.body, %else
  %res = phi i8 [ %call1, %else ], [ %call2, %for.body ]
  ret i8 %res
}

declare i8 @callee()

TARGET (post-transformation IR):
; ModuleID = '<stdin>'
source_filename = "<stdin>"
target datalayout = "e-p:64:64:64-i1:8:8-i8:8:8-i16:16:16-i32:32:32-i64:64:64-f32:32:32-f64:64:64-v64:64:64-v128:128:128-a0:0:64-s0:64:64-f80:128:128-n8:16:32:64"

define i8 @test_drop_icmp_samesign(i1 %cond, i32 range(i32 0, 32) %x) {
entry:
  br i1 %cond, label %for.body.preheader, label %else

for.body.preheader:                               ; preds = %entry
  %0 = trunc i32 %x to i8
  br label %for.body

else:                                             ; preds = %entry
  %call1 = call i8 @callee()
  br label %exit

for.body:                                         ; preds = %for.body.preheader, %for.body
  %call2 = call i8 @callee()
  %cond2 = icmp samesign ugt i8 %0, %call2
  br i1 %cond2, label %for.body, label %exit.loopexit

exit.loopexit:                                    ; preds = %for.body
  %call2.lcssa = phi i8 [ %call2, %for.body ]
  br label %exit

exit:                                             ; preds = %exit.loopexit, %else
  %res = phi i8 [ %call1, %else ], [ %call2.lcssa, %exit.loopexit ]
  ret i8 %res
}

declare i8 @callee()

WHAT THE TRANSFORMATION CHANGED:
  modified:
    %cond2
      source: %cond2 = icmp samesign ugt i32 %x, %ext
      target: %cond2 = icmp samesign ugt i8 %0, %call2
    %res
      source: %res = phi i8 [ %call1, %else ], [ %call2, %for.body ]
      target: %res = phi i8 [ %call1, %else ], [ %call2.lcssa, %exit.loopexit ]
  only in target:
    %0: %0 = trunc i32 %x to i8
    %call2.lcssa: %call2.lcssa = phi i8 [ %call2, %for.body ]
  only in source:
    %ext: %ext = zext i8 %call2 to i32

CRITICAL VALUES:
    %cond2
    %ext
    %res

DEPENDENCY CHAIN (source):
    %call1 = call i8 @callee()
    %call2 = call i8 @callee()
    %ext = zext i8 %call2 to i32
    %cond2 = icmp samesign ugt i32 %x, %ext
    %res = phi i8 [ %call1, %else ], [ %call2, %for.body ]

CONTROL FLOW (blocks entered by the failing execution):
    %exit

